<script setup>
import PageHeader from "../shared/components/PageHeader.vue"
import {computed,nextTick,onMounted,onBeforeUnmount,provide,reactive,ref,watch} from 'vue'
import {ElButton,ElInput} from '../shared/components/ui.js'
import Sel from '../shared/components/Sel.vue'
import PlatformNav from '../shared/components/PlatformNav.vue'
import PlatformPanel from '../shared/components/PlatformPanel.vue'
import ApplicationResourcesEditor from '../deploy/components/ApplicationResourcesEditor.vue'
import DataSyncTasks from '../deploy/components/DataSyncTasks.vue'
import RedisChangeFields from '../deploy/components/RedisChangeFields.vue'
import RedisPlanPreview from '../deploy/components/RedisPlanPreview.vue'
import SQLPlanPreview from '../deploy/components/SQLPlanPreview.vue'
import UiIcon from '../shared/components/UiIcon.vue'
import HelpTip from '../shared/components/HelpTip.vue'
const kind=location.pathname.includes('/redis/')||location.pathname.endsWith('/ui/redis')?'redis':'dbms'
const title=kind==='redis'?'Redis 工作台':'数据库工作台',changeKind=kind==='redis'?'redis':'mysql'
const embedded=window.parent!==window,directAPI=!location.pathname.startsWith('/api/plugins/')
const operationList=ref(false),syncWorkItem=ref(null)
const panel=ref(''),tab=ref('query'),busy=ref(false),loading=ref(false),error=ref(''),keyword=ref('')
const services=ref([]),environments=ref([]),changes=ref([]),runs=ref([]),tickets=ref([]),me=ref({}),aliases=ref([]),queryAliases=ref([])
const form=ref(null),original=ref(''),environment=ref(''),reason=ref(''),plan=ref(null),templateID=ref(0),run=ref(null),queryResult=ref(null),queryTicket=ref(null),recordType=ref('changes')
const showBindings=ref(false),bindingService=ref(''),policy=ref(null),policyDraft=ref({query_approval:false,change_approval:true}),policyError=ref(''),syncResult=ref(null)
const query=reactive({service:'',resource_alias:'',sql:'',commands:''})
const stateLabel={draft:'草稿',ready:'就绪',pending:'待执行',executing:'执行中',success:'成功',pending_approval:'待审核',approved:'待执行',running:'执行中',completed:'完成',failed:'失败',rejected:'已拒绝',canceled:'已取消'}
const nav=computed(()=>[{id:'query',label:'查询',icon:'search'},{id:'operations',label:'变更提交',icon:'changes'},...(kind==='dbms'?[{id:'sync',label:'数据对比同步',icon:'sync'}]:[]),{id:'history',label:'执行记录',icon:'history'}])
function hashNavigation(){const hash=location.hash.slice(1).replace(/^\//,''),[id,params]=hash.split('?');const wid=Number(new URLSearchParams(params).get('work_item'));if(wid>0)syncWorkItem.value={id:wid};if(id==='settings'||nav.value.some(n=>n.id===id)){tab.value=id;if(id==='operations'&&!form.value&&!operationList.value)open()}}
watch(tab,id=>{if(location.hash.slice(1).replace(/^\//,'').split('?')[0]!==id)location.hash=id})
const envOptions=computed(()=>environments.value.map(e=>({value:e.name,label:e.display_name||e.name})))
const filtered=computed(()=>changes.value.filter(c=>!keyword.value||`${c.title} ${c.service}`.toLowerCase().includes(keyword.value.toLowerCase())))
const dirty=computed(()=>form.value&&JSON.stringify(form.value)!==original.value)
const currentEnvironment=computed(()=>environments.value.find(e=>e.name===environment.value))
const changeReview=computed(()=>currentEnvironment.value?.protected||policy.value?.change_approval!==false)
const canReview=computed(()=>run.value&&me.value.username!==run.value.owner&&(run.value.plan.environment.approvers||'').split(',').map(s=>s.trim()).includes(me.value.username))
const canManage=computed(()=>run.value&&(me.value.role==='admin'||me.value.username===run.value.owner))
const canQueryReview=computed(()=>queryTicket.value?.status==='pending_approval'&&queryTicket.value.owner!==me.value.username&&Object.values(queryTicket.value.approvers||{}).every(a=>a.split(',').map(v=>v.trim()).includes(me.value.username)))
const queryOwner=computed(()=>queryTicket.value?.owner===me.value.username)
const statusText=v=>stateLabel[v]||v
async function api(path,opt){const url=path.startsWith('api/')?`api/workbench/${kind}/${path.slice(4)}`:path;const r=await fetch(url,opt),v=await r.json().catch(()=>({}));if(!r.ok)throw new Error(v.error||`请求失败（${r.status}）`);return v}
provide('api',api);provide('resourcePlugin',kind)
const post=(path,body)=>api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})
const list=v=>Array.isArray(v)?v:[]
async function action(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
let activeContext='',policyRequest=0
async function loadPolicy(){const seq=++policyRequest;policy.value=null;policyError.value='';if(!environment.value)return;try{const p=await api(`api/policy?environment=${encodeURIComponent(environment.value)}`);if(seq===policyRequest){policy.value=p;policyDraft.value={...p}}}catch(e){if(seq===policyRequest)policyError.value=e.message}}
async function load(){loading.value=true;try{
 const [apps,envs,ops,history,requests,catalog,identity]=await Promise.all([api('api/services'),api('api/environments'),api('api/changes'),api('api/delivery/runs'),api('api/query-requests'),fetch('/api/registry/applications').then(r=>r.ok?r.json():[]).catch(()=>[]),fetch('/api/me').then(r=>r.ok?r.json():{}).catch(()=>({}))])
 services.value=[...new Map([...list(apps),...list(catalog)].map(a=>[a.name,{name:a.name}])).values()];environments.value=list(envs);changes.value=list(ops);runs.value=list(history);tickets.value=list(requests);me.value=identity
 if(!environments.value.some(e=>e.name===environment.value))environment.value=environments.value.find(e=>e.name===activeContext)?.name||environments.value[0]?.name||''
 if(run.value)run.value=runs.value.find(v=>v.id===run.value.id)||run.value
 if(queryTicket.value)queryTicket.value=tickets.value.find(v=>v.id===queryTicket.value.id)||queryTicket.value
 await loadPolicy()
}catch(e){error.value=e.message}finally{loading.value=false}}
let resourceRequests={query:0,change:0}
async function resourcesFor(service,querying=false){const key=querying?'query':'change',seq=++resourceRequests[key],target=querying?queryAliases:aliases;target.value=[];if(!service)return;try{const data=await api(`api/services/${encodeURIComponent(service)}/resources`);if(seq===resourceRequests[key])target.value=list(data.requirements).filter(r=>r.kind===changeKind).map(r=>({value:r.alias,label:r.alias}))}catch(e){if(seq===resourceRequests[key])error.value=e.message}}
function invalidate(){plan.value=null;templateID.value=0}
watch([environment,reason],invalidate);watch(environment,loadPolicy)
watch(()=>JSON.stringify(form.value),()=>{if(dirty.value)invalidate()})
function navigate(id){if(busy.value)return;if(id==='operations'&&!form.value&&!operationList.value){open();return}tab.value=id;error.value=''}
function open(c){if(busy.value)return;if(dirty.value&&!confirm('放弃未保存的变更？'))return;operationList.value=false;form.value=c?JSON.parse(JSON.stringify(c)):{kind:changeKind,title:'',service:'',risk_level:'medium',rollback_plan:'',sql:kind==='dbms'?{resource_alias:'',content:'',max_affected_rows:100}:undefined,redis:kind==='redis'?{resource_alias:'',commands:''}:undefined};original.value=JSON.stringify(form.value);invalidate();tab.value='operations';error.value='';resourcesFor(form.value.service);return true}
async function save(markReady=false){if(!form.value?.title.trim()||!form.value.service)throw new Error('请填写标题、应用和变更内容');const f=form.value;form.value=await api('api/changes'+(f.id?'/'+f.id:''),{method:f.id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(f)});original.value=JSON.stringify(form.value);if(markReady&&form.value.status!=='ready'){form.value=await post(`api/changes/${form.value.id}/ready`,{});original.value=JSON.stringify(form.value)}invalidate();await load()}
async function preview(){invalidate();if(!form.value||!environment.value)throw new Error('请选择变更和目标环境');if(dirty.value||!form.value.id||form.value.status!=='ready')await save(true);const nodes=[{id:'operation',kind:changeKind,name:title,change_ids:[form.value.id]}];const tpl=await post('api/delivery/templates',{name:`${title}变更`,workbench:kind,mode:'fixed',services:[],nodes});templateID.value=tpl.id;plan.value=await post('api/delivery/preview',{template_id:tpl.id,environment:environment.value,reason:reason.value,nodes})}
async function submit(){if(!plan.value||!templateID.value||plan.value.blockers?.length)throw new Error('请先完成预检并解决阻断项');run.value=await post('api/delivery/runs',{template_id:templateID.value,environment:environment.value,reason:reason.value,nodes:plan.value.nodes});invalidate();tab.value='history';recordType.value='changes';await load()}
async function runAction(name){if(name==='advance'&&!confirm('执行此快照中的变更？请核对目标环境。'))return;run.value=await post(`api/delivery/runs/${run.value.id}/${name}`,{digest:run.value.digest});await load()}
async function bind(){bindingService.value=tab.value==='query'?query.service:form.value?.service;if(!bindingService.value)throw new Error('请先选择应用');await post('api/applications',{name:bindingService.value});showBindings.value=true}
async function readQuery(){queryResult.value=null;if(!policy.value)throw new Error('审批设置尚未加载，不能执行查询');if(!query.service||!query.resource_alias||!environment.value)throw new Error('请选择应用、资源和环境');if(!(kind==='dbms'?query.sql:query.commands).trim())throw new Error('请先填写查询内容');const body={...query,environment:environment.value};if(policy.value.query_approval){queryTicket.value=await post('api/query-requests',body);recordType.value='queries';tab.value='history';await load()}else queryResult.value=await post('api/query',body)}
async function ticketAction(name){const data=await post(`api/query-requests/${queryTicket.value.id}/${name}`,{});if(name==='execute'){queryTicket.value=data.ticket;if(data.ticket.query.task_id){syncResult.value={ticket:data.ticket,result:data.result};tab.value='sync'}else{Object.assign(query,data.ticket.query);environment.value=data.ticket.query.environment;await resourcesFor(query.service,true);await nextTick();queryResult.value=data.result;tab.value='query'}}else queryTicket.value=data;await load()}
async function approveComparison(q){await action(async()=>{queryTicket.value=await post('api/query-requests',q);recordType.value='queries';tab.value='history';await load()})}
async function savePolicy(){if(me.value.role!=='admin')throw new Error('仅管理员可修改审批设置');if(!confirm('保存当前环境的查询与变更审批设置？不会执行查询或变更。'))return;policy.value=await api(`api/policy?environment=${encodeURIComponent(environment.value)}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(policyDraft.value)});policyDraft.value={...policy.value};invalidate()}
watch([environment,()=>query.service,()=>query.resource_alias,()=>query.sql,()=>query.commands],()=>queryResult.value=null)
function closeEditor(){operationList.value=true;invalidate()}
function syncGenerated(){load();if(embedded&&syncWorkItem.value)window.parent.postMessage({type:'work-item.changed',id:syncWorkItem.value.id},location.origin)}
function queryToChange(){if(busy.value||!open())return;form.value.service=query.service;if(kind==='dbms'){form.value.sql.resource_alias=query.resource_alias;form.value.sql.content=query.sql}else{form.value.redis.resource_alias=query.resource_alias;form.value.redis.commands=query.commands}resourcesFor(query.service)}
function contextMessage(e){if(e.source===window.parent&&e.origin===location.origin&&e.data?.type==='context.sync'){activeContext=e.data.environment;if(!environment.value&&environments.value.some(v=>v.name===activeContext))environment.value=activeContext}}
function beforeUnload(e){if(dirty.value){e.preventDefault();e.returnValue=''}}
onMounted(()=>{hashNavigation();load();window.addEventListener('hashchange',hashNavigation);window.addEventListener('message',contextMessage);window.addEventListener('beforeunload',beforeUnload);if(embedded)window.parent.postMessage({type:'context.request'},location.origin)})
onBeforeUnmount(()=>{window.removeEventListener('hashchange',hashNavigation);window.removeEventListener('message',contextMessage);window.removeEventListener('beforeunload',beforeUnload)})
</script>
<template>
<div class="layout" :class="{embedded}">
 <header class="workspace-sidebar"><b><UiIcon :name="kind"/><span>{{kind==='redis'?'Redis':'DBMS'}}</span></b><nav aria-label="工作台导航"><button v-for="n in nav" :key="n.id" :class="{active:tab===n.id}" :aria-current="tab===n.id?'page':undefined" @click="navigate(n.id)"><UiIcon :name="n.icon"/><i>{{n.label}}</i></button></nav><PlatformNav @open="panel=$event"/></header>
 <main><PageHeader :title="title"><template #navigation><nav class="primary-modes" aria-label="主要操作"><button :class="{active:tab==='query'}" @click="navigate('query')">{{kind==='dbms'?'SQL 查询':'命令查询'}}</button><button :class="{active:tab==='operations'}" @click="navigate('operations')">{{kind==='dbms'?'提交 SQL':'提交命令变更'}}</button><button v-if="kind==='dbms'" :class="{active:tab==='sync'}" @click="navigate('sync')">数据对比同步</button></nav></template><template #actions><ElButton :disabled="busy||loading" @click="load">刷新</ElButton><ElButton @click="navigate('settings')"><UiIcon name="settings"/>审批设置</ElButton></template></PageHeader>
  <p v-if="me.auth_enabled===false" class="notice">未启用登录时无法保障双人审核；启用审批前请先配置登录与环境审核人。</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="policyError" class="error" role="alert">{{policyError}}</p>
  <div v-if="tab!=='sync'&&tab!=='history'" class="scope"><label>目标环境<Sel v-model="environment" :options="envOptions" :disabled="busy" filterable width="210px"/></label><span class="policy-badge" v-if="policy">{{tab==='query'?(policy.query_approval?'查询需审批':'查询无需审批'):(changeReview?'变更需审批':'变更无需审批')}}<small v-if="currentEnvironment?.protected&&tab!=='query'"> · 受保护环境</small></span></div>
  <section v-show="tab==='query'" class="card query"><div class="section-head"><h3>{{kind==='dbms'?'SQL 查询':'Redis 查询'}}</h3><div class="buttons"><HelpTip :text="kind==='dbms'?'只读查询：单表 SELECT + WHERE、显式字段。最多 1000 行 / 2 MiB，30 秒超时。不支持 *、JOIN、函数、排序、LIMIT、多语句；结果不写入审计日志。':'只读命令：GET、TYPE、TTL、PTTL、EXISTS、STRLEN、HLEN、LLEN、SCARD、ZCARD、PING。仅精确 Key 与资源允许的前缀；GET 超过 64 KiB 截断。'"/><ElButton type="primary" :loading="busy" :disabled="!policy" @click="action(readQuery)">{{policy?.query_approval?'提交查询申请':'执行只读查询'}}</ElButton></div></div><div class="grid"><label>应用<Sel v-model="query.service" :options="services.map(s=>s.name)" :disabled="busy" filterable width="100%" @change="query.resource_alias='';resourcesFor(query.service,true)"/></label><label>{{kind==='dbms'?'逻辑数据库资源':'逻辑 Redis 资源'}}<Sel v-model="query.resource_alias" :options="queryAliases" :disabled="busy" width="100%"/></label><label class="full">{{kind==='dbms'?'查询 SQL':'查询命令（每行一条）'}}<ElInput v-if="kind==='dbms'" v-model="query.sql" type="textarea" :rows="7" :disabled="busy"/><ElInput v-else v-model="query.commands" type="textarea" :rows="7" :disabled="busy"/></label></div>
   <div class="query-secondary"><ElButton :disabled="busy" @click="queryToChange">以此新建变更</ElButton><details v-if="me.role==='admin'"><summary>找不到资源？</summary><ElButton :disabled="!query.service||busy" @click="action(bind)">配置资源绑定</ElButton></details></div>
   <div v-if="queryResult" class="results"><div class="section-head"><h3>查询结果</h3><small>{{(queryResult.rows||[]).length}} 行</small></div><div class="table-scroll"><table><thead><tr><th v-for="c in queryResult.columns" :key="c">{{c}}</th></tr></thead><tbody><tr v-for="(row,i) in queryResult.rows" :key="i"><td v-for="c in queryResult.columns" :key="c">{{row[c]===null?'NULL':row[c]}}</td></tr></tbody></table></div><p v-if="!queryResult.rows?.length" class="empty">没有匹配的数据。</p></div>
  </section>
  <section v-show="tab==='operations'" class="card"><template v-if="!form||operationList"><div class="section-head"><h3>可复用变更</h3><ElButton type="primary" @click="open()">＋ 新建变更</ElButton><ElButton v-if="form&&dirty" @click="operationList=false">继续编辑草稿</ElButton><ElInput v-model="keyword" placeholder="筛选标题或应用" clearable/></div><div class="table-scroll"><table><thead><tr><th>变更</th><th>应用</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="c in filtered" :key="c.id"><td><b>{{c.title}}</b><small class="sub">#{{c.id}}</small></td><td>{{c.service}}</td><td>{{statusText(c.status)}}</td><td><ElButton size="small" @click="open(c)">编辑 / 提交</ElButton></td></tr></tbody></table></div><p v-if="!filtered.length" class="empty">{{keyword?'没有匹配的变更':'暂无变更。新建一次后可在不同环境复用。'}}</p></template>
   <div v-else class="editor"><div class="section-head"><h3>{{form.id?'变更 #'+form.id:'新建变更'}}</h3><div class="buttons"><ElButton :disabled="busy" @click="closeEditor">已有变更</ElButton><ElButton v-if="form.status!=='ready'" :loading="busy" @click="action(()=>save())">保存草稿</ElButton><ElButton type="primary" :loading="busy" @click="action(preview)">预检变更</ElButton></div></div><div class="grid"><label class="full">标题<ElInput v-model="form.title" :disabled="busy||form.status==='ready'"/></label><label>应用<Sel v-model="form.service" :options="services.map(s=>s.name)" :disabled="busy||form.status==='ready'" filterable width="100%" @change="form[changeKind==='mysql'?'sql':'redis'].resource_alias='';resourcesFor(form.service)"/></label><label>逻辑资源别名<Sel v-model="form[changeKind==='mysql'?'sql':'redis'].resource_alias" :options="aliases" :disabled="busy||form.status==='ready'" width="100%"/></label><template v-if="kind==='dbms'"><label class="full">SQL 变更<ElInput v-model="form.sql.content" type="textarea" :rows="8" :disabled="busy||form.status==='ready'||!!form.sql.data_sync"/></label><label>最多影响行数<ElInput v-model.number="form.sql.max_affected_rows" type="number" :disabled="busy||form.status==='ready'"/></label></template><RedisChangeFields v-else :model="form.redis" :disabled="busy||form.status==='ready'"/><label class="full">恢复方案<ElInput v-model="form.rollback_plan" type="textarea" :rows="2" :disabled="busy||form.status==='ready'" placeholder="说明失败后的人工核对与恢复步骤"/></label><label class="full">本次变更原因<ElInput v-model="reason" :disabled="busy" placeholder="随执行单记录，不写入可复用变更"/></label></div>
   <div class="actions"><ElButton v-if="form.status==='ready'" :disabled="busy" @click="action(async()=>{form=await post(`api/changes/${form.id}/draft`,{});original=JSON.stringify(form);invalidate()})">退回草稿修改</ElButton><details v-if="me.role==='admin'"><summary>资源设置</summary><ElButton :disabled="busy||!form.service" @click="action(bind)">配置资源绑定</ElButton></details></div>
   <section v-if="plan" class="preview"><h3>确认变更 · {{plan.environment.display_name||plan.environment.name}}</h3><p class="hint">预检不会执行变更。提交后{{plan.environment.protected||plan.workbench_policy?.change_approval!==false?'需审核，再由发起人执行':'仍需手动确认执行'}}。</p><p v-for="b in plan.blockers||[]" :key="b" class="error">{{b}}</p><p v-for="w in plan.warnings||[]" :key="w" class="hint">{{w}}</p><SQLPlanPreview :plans="plan.sql_plans"/><RedisPlanPreview :plans="plan.redis_plans"/><ElButton type="primary" :loading="busy" :disabled="!!plan.blockers?.length" @click="action(submit)">{{plan.environment.protected||plan.workbench_policy?.change_approval!==false?'提交审核（不执行）':'创建执行单（不执行）'}}</ElButton></section></div>
  </section>
  <section v-show="tab==='history'" class="card history"><div class="section-head"><h3>执行记录</h3><div class="buttons"><ElButton :type="recordType==='changes'?'primary':''" @click="recordType='changes';run=null;queryTicket=null">变更记录</ElButton><ElButton :type="recordType==='queries'?'primary':''" @click="recordType='queries';run=null;queryTicket=null">查询申请</ElButton></div></div>
   <template v-if="recordType==='changes'&&!run"><div class="table-scroll"><table><thead><tr><th>执行单</th><th>目标环境</th><th>状态</th><th>发起人</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="v in runs" :key="v.id"><td>#{{v.id}}</td><td>{{v.plan.environment.display_name||v.plan.environment.name}}</td><td>{{statusText(v.status)}}</td><td>{{v.owner}}</td><td>{{new Date(v.created_at*1000).toLocaleString('zh-CN')}}</td><td><ElButton size="small" @click="run=v">查看 / 审核</ElButton></td></tr></tbody></table></div><p v-if="!runs.length" class="empty">暂无变更执行单。</p></template>
   <template v-else-if="recordType==='changes'&&run"><div class="section-head"><h3>变更执行单 #{{run.id}}</h3><ElButton @click="run=null">返回记录列表</ElButton></div><p>{{run.plan.environment.display_name||run.plan.environment.name}} · {{statusText(run.status)}} · 发起 {{run.owner}} · 审核 {{run.approver||'—'}}</p><p>变更原因：{{run.plan.reason||'未填写'}}</p><details><summary>快照摘要</summary><code>{{run.digest}}</code></details><SQLPlanPreview :plans="run.plan.sql_plans"/><RedisPlanPreview :plans="run.plan.redis_plans"/><article v-for="s in run.steps||[]" :key="s.node_id"><b>{{s.name}} · {{statusText(s.status)}}</b><pre>{{s.detail||'等待执行'}}</pre></article><div class="actions"><template v-if="run.status==='pending_approval'&&canReview"><ElButton :loading="busy" @click="action(()=>runAction('reject'))">拒绝</ElButton><ElButton type="primary" :loading="busy" @click="action(()=>runAction('approve'))">批准此快照</ElButton></template><ElButton v-if="['approved','running'].includes(run.status)&&canManage" type="primary" :loading="busy" @click="action(()=>runAction('advance'))">确认执行 / 继续</ElButton><ElButton v-if="['approved','pending_approval'].includes(run.status)&&canManage" :loading="busy" @click="action(()=>runAction('cancel'))">取消执行单</ElButton><ElButton @click="navigate('operations')">返回变更编辑</ElButton></div></template>
   <template v-else-if="!queryTicket"><div class="table-scroll"><table><thead><tr><th>申请</th><th>类型</th><th>状态</th><th>申请人</th><th>操作</th></tr></thead><tbody><tr v-for="v in tickets" :key="v.id"><td>#{{v.id}}</td><td>{{v.query.task_id?'数据对比':'只读查询'}}</td><td>{{statusText(v.status)}}</td><td>{{v.owner}}</td><td><ElButton size="small" @click="queryTicket=v">查看 / 审核</ElButton></td></tr></tbody></table></div><p v-if="!tickets.length" class="empty">暂无查询申请。</p></template>
   <template v-else><div class="section-head"><h3>查询申请 #{{queryTicket.id}}</h3><ElButton @click="queryTicket=null">返回记录列表</ElButton></div><p>{{statusText(queryTicket.status)}} · 申请人 {{queryTicket.owner}} · 审核人 {{queryTicket.approver||'—'}}</p><p>环境：{{Object.keys(queryTicket.approvers||{}).join(' → ')}} · 30 分钟内有效，批准后仅申请人可执行一次。</p><pre>{{queryTicket.query.task_id?'数据对比任务 #'+queryTicket.query.task_id:kind==='dbms'?queryTicket.query.sql:queryTicket.query.commands}}</pre><div class="actions"><template v-if="canQueryReview"><ElButton @click="action(()=>ticketAction('reject'))">拒绝查询</ElButton><ElButton type="primary" @click="action(()=>ticketAction('approve'))">批准查询</ElButton></template><ElButton v-if="queryTicket.status==='approved'&&queryOwner" type="primary" :loading="busy" @click="action(()=>ticketAction('execute'))">执行已批准查询</ElButton></div></template>
  </section>
  <section v-if="kind==='dbms'" v-show="tab==='sync'" class="card sync-page"><div v-if="syncWorkItem" class="association-note">生成的同步草稿关联需求 / Bug #{{syncWorkItem.id}}<ElButton size="small" @click="syncWorkItem=null">解除本次关联</ElButton></div><DataSyncTasks inline :show="true" :services="services" :environments="environments" :approved-comparison="syncResult" :item="syncWorkItem" @query-approval="approveComparison" @close="navigate('query')" @generated="syncGenerated" @preview="c=>{open(c);environment=c.sql.data_sync.target_environment}"/></section>
  <section v-show="tab==='settings'" class="card settings"><h3>审批设置 · {{currentEnvironment?.display_name||environment||'请选择环境'}}</h3><p class="hint">查询与变更互不影响，DBMS 和 Redis 分别配置。审核人沿用目标环境的审核人员。</p><div class="policy-row"><div><b>查询审批</b><p>开启后只读查询需先批准；数据库的数据对比也遵循两侧查询策略。</p></div><label><input type="checkbox" v-model="policyDraft.query_approval" :disabled="busy||!policy||me.role!=='admin'"/>需要审批</label></div><div class="policy-row"><div><b>变更审批</b><p>开启后写操作需另一名审核人批准；关闭后仍须预检、创建执行单、手动确认执行。</p></div><label><input type="checkbox" v-model="policyDraft.change_approval" :disabled="busy||!policy||me.role!=='admin'"/>需要审批</label></div><p v-if="currentEnvironment?.protected" class="notice">此环境受保护，变更始终需要审批；该开关仅作用于非保护环境。</p><p>审核人：{{currentEnvironment?.approvers||'未配置，请到资源中心 → 环境设置'}}</p><div class="actions"><ElButton type="primary" :loading="busy" :disabled="!policy||me.role!=='admin'" @click="action(savePolicy)">保存审批设置</ElButton><small>{{me.role==='admin'?'仅修改当前工作台、当前环境；历史已提交快照不会因此免审。':'仅管理员可修改设置。'}}</small></div></section>
 </main>
 <PlatformPanel :view="panel" :plugin="kind" :directAPI="directAPI" @switch="panel=$event" @close="panel='';load()"/>
 <ApplicationResourcesEditor :show="showBindings" :services="services" :initial-service="bindingService" @close="showBindings=false;resourcesFor(bindingService,tab==='query')"/>
</div>
</template>
